svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg";
  var W = 1200, H = 600;
  var FONT = 18, COLW = 18;
  var COLS = Math.floor(W / COLW);
  var ROWS = Math.floor(H / FONT) + 2;

  var GLYPHS = "アァイィウゥエェオォカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲンガギグゲゴザジズゼゾダヂヅデドバビブベボパピプペポヴッ0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ:=*+-<>¦｜";
  var GLEN = GLYPHS.length;

  var rain = document.getElementById("rain");
  rain.setAttribute("font-family", "'MS Gothic','Hiragino Kaku Gothic ProN','Noto Sans JP','Courier New',monospace");
  rain.setAttribute("font-size", FONT);
  rain.setAttribute("font-weight", "bold");
  rain.setAttribute("text-anchor", "middle");

  var columns = [];
  var frag = document.createDocumentFragment();

  for (var c = 0; c < COLS; c++) {
    var g = document.createElementNS(NS, "g");
    var cells = new Array(ROWS);
    var alphas = new Array(ROWS);
    var fills = new Array(ROWS);
    var x = (c * COLW + COLW / 2).toFixed(1);

    for (var r = 0; r < ROWS; r++) {
      var t = document.createElementNS(NS, "text");
      t.setAttribute("x", x);
      t.setAttribute("y", ((r + 1) * FONT - 4).toFixed(1));
      t.setAttribute("opacity", "0");
      t.setAttribute("fill", "#00ff41");
      t.textContent = GLYPHS.charAt((Math.random() * GLEN) | 0);
      g.appendChild(t);
      cells[r] = t;
      alphas[r] = 0;
      fills[r] = "#00ff41";
    }

    frag.appendChild(g);
    columns.push({
      head: (Math.random() * ROWS) | 0,
      len: 8 + ((Math.random() * 18) | 0),
      interval: 35 + Math.random() * 80,
      acc: Math.random() * 60,
      cells: cells,
      alphas: alphas,
      fills: fills
    });
  }
  rain.appendChild(frag);

  function draw(col) {
    var head = col.head, len = col.len;

    for (var r = 0; r < ROWS; r++) {
      var d = head - r;
      var a = 0, fill = "#00ff41";

      if (d >= 0 && d <= len) {
        if (d === 0) {          // 头字符：偏白高亮
          a = 1;
          fill = "#d6ffdd";
        } else {                 // 拖尾：指数衰减
          a = Math.pow(1 - d / len, 1.9);
        }
      }

      var q = a < 0.03 ? 0 : Math.round(a * 100) / 100;
      var cell = col.cells[r];

      if (q !== col.alphas[r]) {
        cell.setAttribute("opacity", q);
        col.alphas[r] = q;
      }

      if (q > 0) {
        if (fill !== col.fills[r]) {
          cell.setAttribute("fill", fill);
          col.fills[r] = fill;
        }
        if (Math.random() < 0.3) {   // 随机跳字
          cell.textContent = GLYPHS.charAt((Math.random() * GLEN) | 0);
        }
      }
    }
  }

  for (var i = 0; i < columns.length; i++) draw(columns[i]);

  var last = 0;
  function frame(now) {
    if (!last) last = now;
    var dt = now - last;
    last = now;
    if (dt > 250) dt = 250;

    for (var i = 0; i < columns.length; i++) {
      var col = columns[i];
      col.acc += dt;
      var guard = 0;

      while (col.acc >= col.interval && guard++ < 3) {
        col.acc -= col.interval;
        col.head++;

        if (col.head - col.len > ROWS) {     // 归位到屏幕上方
          col.head = -((Math.random() * 30) | 0) - 1;
          col.len = 8 + ((Math.random() * 20) | 0);
          col.interval = 35 + Math.random() * 80;
        }
        draw(col);
      }
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
